head=f'''<header class="cover"><div class="eyebrow">VOICECHAT / ORIGINAL NOCTURNE / MOBILE ATLAS</div><h1>Все разговоры.<br><span>В пределах экрана.</span></h1><p>Исходный Nocturne — без смены палитры. Полный каталог мобильных экранов и ключевых состояний, сверенный с функциями Flutter-клиента. Android и мобильный веб показаны в фиксированных размерах телефона, с нормальной прокруткой и компактными сообщениями.</p><div class="metrics"><span>{len(SCREENS)} ЭКРАНОВ И СОСТОЯНИЙ</span><span>ANDROID + MOBILE WEB</span><span>390 × 844 / 360 × 800 / 320 × 568</span></div></header>'''
controls='''<nav class="toolbar" aria-label="Каталог макетов"><div class="control"><label for="platform">Платформа</label><select id="platform"><option value="android">Android</option><option value="web">Мобильный веб</option></select></div><div class="control"><label for="size">Размер телефона</label><select id="size"><option value="390,844">390 × 844</option><option value="360,800">360 × 800</option><option value="320,568">320 × 568</option></select></div><div class="control"><label for="category">Раздел</label><select id="category"><option value="all">Все разделы</option>'''+''.join(f'<option>{g}</option>' for g in groups)+'''</select></div><div class="control"><label for="screenSelect">Экран</label><select id="screenSelect"><option value="all">Все экраны</option>'''+''.join(f'<option value="{s["key"]}">{i:02} · {s["label"]}</option>' for i,s in enumerate(SCREENS,1))+'''</select></div><div class="control"><label for="find">Поиск по функциям</label><input id="find" class="catalogsearch" placeholder="Например: ключи"></div><div class="control"><label for="scale">Масштаб текста</label><select id="scale"><option value="1">100%</option><option value="1.25">125%</option></select></div><button id="all">Весь каталог</button><button id="chrome">Панели браузера: видны</button></nav>'''
intro='''<section class="intro"><div><h2>01 / Пузырьки по содержимому</h2><p>Свои справа, чужие слева. Текст 16 px, максимум 82% ширины ленты, промежуток 4 px. Голосовое компактнее текстового экрана, без огромной пустой карточки. В группе подписан автор чужого сообщения.</p></div><div><h2>02 / Высота настоящего телефона</h2><p>390 × 844 — полный внутренний размер макета, включая статус и нижнюю системную область. Для web панели браузера занимают ещё 88 px внутри той же высоты. Это честная модель доступного места, а не снимок конкретной ОС.</p></div><div><h2>03 / Прокрутка вместо растягивания</h2><p>Шапка и ввод закреплены. Длинные формы, настройки и участники прокручиваются в центральной области. Клавиатура занимает 240 px внутри телефона, на компактном экране — 200 px. Вы можете прокрутить каждый макет и перейти по подписанным действиям к другому референсу.</p></div></section><div class="readout" id="readout" aria-live="polite"></div>'''
articles=[]
for i,s in enumerate(SCREENS,1):
 back='people'
 if s['group']=='Аккаунт':back='login'
 elif s['group'] in ['Переписка','Медиа','Время и поиск','Звонки','Демонстрация экрана']:back='chat'
 elif s['group']=='Безопасность':back='security'
 elif s['group']=='Настройки':back='settings'
 app=(s['content'] if s['custom'] else '<div class="appbar">'+ib('back','Назад',back)+f'<h3>{s["label"]}</h3>'+ib('close','Закрыть','people')+'</div>'+s['content'])
 articles.append(f'''<article class="screen-card" id="{s['key']}" data-group="{s['group']}" data-platform="{s['platform']}" data-search="{html.escape((s['label']+' '+s['functions']).lower(),quote=True)}"><div class="screen-label"><span>{i:02}</span><h2>{s['label']}</h2></div><div class="frame"><div class="viewport"><div class="status"><span>9:41</span><span>••• ▰</span></div><div class="browserchrome">{ic('lock')}<span class="address">voicechat.example.test</span><span>⋯</span></div><div class="app">{app}</div><div class="browserbottom">{ic('back')}{ic('refresh')}{ic('plus')}{ic('more')}</div><div class="systembar"></div></div></div><div class="screen-info"><b>{s['group']}</b><br>{s['functions']}<details><summary>Компоновка и источник</summary><p>{s['layout'] or 'Высота фиксирована. Центральная область прокручивается; основные действия доступны в пределах viewport.'}</p><p>Код: {s['source']}</p></details></div></article>''')
manifest=[{k:v for k,v in s.items() if k!='content'} for s in SCREENS]
coverage=''.join(f'<tr><td>{i:02}</td><td><a href="#{s["key"]}" data-go="{s["key"]}">{s["label"]}</a></td><td>{s["source"]}</td><td>{s["functions"]}</td></tr>' for i,s in enumerate(SCREENS,1))
end='''<footer class="footer-doc"><h2>Охват — видимый и проверяемый.</h2><p>Макеты покрывают пользовательские поверхности текущего клиента: аккаунт, контакты, группы, переписку и состояния редактора, медиа, расписание, вызовы, настройки, ключи и экспериментальную демонстрацию. Независимые системные окна Android/браузера — выбор файлов, разрешения, маршруты аудио и захват экрана — обозначены как системные, а не нарисованы как часть VoiceChat.</p><p>Это авторские макеты по текущему коду, а не снимки работающего Flutter-приложения. Переходы внутри артбука служат навигацией по референсам; они не отправляют сообщения, не отзывают сеансы и не включают камеру. Контакты, идентификаторы, медиа и секреты вымышлены. Ошибки, состояния загрузки и ожидания сгруппированы по пользовательскому действию; каждое возможное сетевое исключение не получает отдельный экран.</p><p>Изменения навигации (отдельные страницы вместо высоких модальных окон, меню поиска/даты) — предложения UX, функции сохранены в каталоге. Для внедрения нужна проверка реальных Flutter-виджетов, локализации, клавиатуры, TalkBack и устройств. Проверка размеров HTML не доказывает работоспособность звонков или E2EE.</p><details><summary>Матрица экранов → функций → исходного кода</summary><table class="coverage"><thead><tr><th>№</th><th>Экран</th><th>Источник в apps/client/lib</th><th>Функции</th></tr></thead><tbody>'''+coverage+'''</tbody></table></details><p><a href="../artbook-2026-10/index.html#nocturne">Исходный Nocturne</a> · <a href="inventory.json">Инвентаризация JSON</a></p></footer><div class="toast" id="toast" hidden role="status">Это визуальный референс. Действие не выполняется.</div>'''
js=r'''
const platform=document.querySelector('#platform'),size=document.querySelector('#size'),category=document.querySelector('#category'),screenSelect=document.querySelector('#screenSelect'),find=document.querySelector('#find'),scale=document.querySelector('#scale');const cards=[...document.querySelectorAll('.screen-card')];let noChrome=false;
function update(){const [w,h]=size.value.split(',').map(Number);document.documentElement.style.setProperty('--vw',w+'px');document.documentElement.style.setProperty('--vh',h+'px');document.documentElement.style.setProperty('--textscale',scale.value);document.body.classList.toggle('web',platform.value==='web');document.body.classList.toggle('compact',w<=320);document.body.classList.toggle('chrome-hidden',noChrome);let count=0;for(const c of cards){c.hidden=!(c.dataset.platform==='both'||c.dataset.platform===platform.value)||(category.value!=='all'&&c.dataset.group!==category.value)||(screenSelect.value!=='all'&&c.id!==screenSelect.value)||!c.dataset.search.includes(find.value.trim().toLowerCase());if(!c.hidden)count++;}document.querySelector('#readout').textContent=`Показано: ${count} · ${platform.value==='web'?'Мобильный веб':'Android'} · телефон ${w} × ${h} px · область приложения ${h-44-(platform.value==='web'&&!noChrome?88:0)} px · прокрутка внутри макетов`;requestAnimationFrame(()=>document.querySelectorAll('.timeline').forEach(el=>{el.scrollTop=el.scrollHeight}));}
function go(id){const card=document.getElementById(id);if(!card?.classList.contains('screen-card'))return;if(card.dataset.platform!=='both')platform.value=card.dataset.platform;category.value='all';find.value='';screenSelect.value=id;update();history.replaceState(null,'','#'+id);card.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
for(const el of [platform,size,category,screenSelect,scale])el.addEventListener('change',update);find.addEventListener('input',update);document.querySelector('#all').onclick=()=>{category.value='all';screenSelect.value='all';find.value='';update()};document.querySelector('#chrome').onclick=()=>{noChrome=!noChrome;document.querySelector('#chrome').textContent='Панели браузера: '+(noChrome?'скрыты':'видны');update()};document.addEventListener('click',e=>{const target=e.target.closest('[data-go]');if(target){e.preventDefault();go(target.dataset.go)}else if(e.target.closest('[data-demo]')){const toast=document.querySelector('#toast');toast.hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>toast.hidden=true,3000)}});if(innerWidth<380)size.value='320,568';else if(innerWidth<420)size.value='360,800';update();if(location.hash)go(decodeURIComponent(location.hash.slice(1)));
'''
keys=[s['key'] for s in SCREENS]
assert len(keys)==len(set(keys))
import re
for s in SCREENS:
 for target in re.findall('data-go="([^"]+)"',s['content']):assert target in keys,(s['key'],target)
(OUT/'inventory.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2))
(OUT/'index.html').write_text('<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nocturne — полный мобильный артбук VoiceChat</title><style>'+CSS+'</style>'+head+controls+intro+'<main class="gallery">'+''.join(articles)+'</main>'+end+'<script>'+js+'</script></html>')
print(f'Built {len(SCREENS)} screens: '+', '.join(f'{g}: {sum(s["group"]==g for s in SCREENS)}' for g in groups))
